'use strict';
// Separate period-based first-party readings from dated lifetime platform counters.
const metricAnchor=new Date('2026-11-03T12:00:00Z');
const externalSamples=[{owner:'org',articleId:'identity',channel:'dev',capturedAt:'2026-11-03T10:00:00Z',views:1840,reactions:32,comments:0},{owner:'org',articleId:'identity',channel:'hashnode',capturedAt:'2026-10-20T10:00:00Z',views:620,reactions:0,comments:null}];
function metricPool(){return articles.filter(a=>a.owner===state.workspace&&(site.analyticsArticle==='all'||site.analyticsArticle===a.id)&&Object.keys(a.langs).some(l=>(site.analyticsLang==='all'||site.analyticsLang===l)&&isPublic(a,l)));}
function externalCounters(){const from=+metricAnchor-Number(site.analyticsPeriod)*86400000;return site.analyticsLang==='zh'?[]:externalSamples.filter(x=>x.owner===state.workspace&&x.channel===site.analyticsSource&&(site.analyticsArticle==='all'||x.articleId===site.analyticsArticle)&&+new Date(x.capturedAt)>=from&&+new Date(x.capturedAt)<=+metricAnchor);}
function ghostMetricData(){const pool=metricPool();const days=Number(site.analyticsPeriod);const points=Array.from({length:days},(_,i)=>({day:new Date(+metricAnchor-(days-1-i)*86400000).toISOString().slice(0,10),views:pool.length?(52+(i*19)%48)*pool.length:0,dailyUV:pool.length?(28+(i*7)%21)*pool.length:0}));return {pool,points,views:points.reduce((n,p)=>n+p.views,0),dailyUV:Math.round(points.reduce((n,p)=>n+p.dailyUV,0)/days)};}
function counterMetric(rows,key){const available=rows.filter(r=>r[key]!==null&&r[key]!==undefined);return {value:available.length?available.reduce((n,r)=>n+r[key],0):null,coverage:`${available.length}/${rows.length}`,updated:available.map(r=>r.capturedAt).sort().at(-1)||null};}
function metricCard(label,value,source,definition,coverage,updated){return `<article class="panel metric-card"><span>${label}</span><strong>${value===null?'Unavailable':Number(value).toLocaleString()}</strong><p>${definition}</p><small>${txt('来源','Source')}: ${source}<br>${txt('覆盖','Coverage')}: ${coverage}<br>${txt('更新','Updated')}: ${updated||'—'}</small></article>`;}
analyticsPage=function(){const pool=articles.filter(a=>a.owner===state.workspace&&Object.keys(a.langs).some(l=>isPublic(a,l)));return titleBlock('UNDERSTAND YOUR IMPACT','数据分析',txt('阅读、平台累计计数和分发结果分别呈现。所有数值均为演示数据。','Readership, platform lifetime counters and distribution outcomes are separate. All values are sample data.'),btn('导出当前数据','export-analytics','','download'))+`<div class="analytics-filter panel"><label>${txt('时间范围','Date range')}<select id="analytics-period">${['7','30','90'].map(n=>`<option value="${n}" ${site.analyticsPeriod===n?'selected':''}>${n} ${txt('天','days')}</option>`).join('')}</select></label><label>${txt('文章','Article')}<select id="analytics-article"><option value="all">${txt('全部公开文章','All public articles')}</option>${pool.map(a=>`<option value="${a.id}" ${site.analyticsArticle===a.id?'selected':''}>${esc(displayLanguage(a).savedTitle)}</option>`).join('')}</select></label><label>${txt('语言','Language')}<select id="analytics-lang">${[['all','全部语言','All languages'],['en','English','English'],['zh','简体中文','简体中文']].map(([v,z,e])=>`<option value="${v}" ${v===site.analyticsLang?'selected':''}>${txt(z,e)}</option>`).join('')}</select></label><label>${txt('数据来源','Data source')}<select id="analytics-source">${[['ghost','Ghost · 原文','Ghost · original'],...channelCatalog.map(c=>[c.id,c.name,c.name])].map(([v,z,e])=>`<option value="${v}" ${site.analyticsSource===v?'selected':''}>${txt(z,e)}</option>`).join('')}</select></label></div>${analyticsResults()}${distributionInsights()}`;};pageRenderers.analytics=analyticsPage;
analyticsResults=function(){const source=site.analyticsSource;if(source==='ghost'){const d=ghostMetricData();const max=Math.max(1,...d.points.map(p=>p.views));return notice(txt('Ghost：所选区间内的原文阅读。日 UV 平均值来自每日估算，不是跨日去重人数。演示基准日期为 2026-11-03。','Ghost: original readership during the selected interval. Average daily UV is based on daily estimates, not deduplicated visitors across days. Sample reference date: 2026-11-03.'))+`<div class="metrics-grid">${metricCard(txt('区间浏览量','Period views'),d.views,'Ghost',txt('当前筛选下的阅读事件','Read events in the current filter'),d.pool.length+' '+txt('篇文章','articles'),'2026-11-03 12:00 UTC')}${metricCard(txt('日均估算 UV','Average daily estimated UV'),d.dailyUV,'Ghost',txt('每日估算 UV 的算术平均值','Arithmetic mean of daily UV estimates'),site.analyticsPeriod+' '+txt('天','days'),'2026-11-03 12:00 UTC')}</div><section class="panel chart-panel"><h2>${txt('原文阅读趋势','Original readership trend')}</h2><div class="readership-bars" aria-label="${txt('区间阅读柱状图','Period readership bar chart')}">${d.points.map(p=>`<span title="${p.day}: ${p.views}" style="height:${Math.max(2,p.views/max*100)}%"></span>`).join('')}</div><div class="chart-range"><span>${d.points[0].day}</span><span>${d.points.at(-1).day}</span></div></section>`;}const rows=externalCounters();return notice(txt('外部渠道显示最近一次采集的累计计数。日期筛选限定采集时间，不表示区间新增，也不计算跨平台独立读者。','External channels show the latest captured lifetime counters. Date filters apply to capture time, not growth during the interval; readers are never deduplicated across platforms.'))+`<div class="metrics-grid three">${[['views','累计浏览','Lifetime views'],['reactions','累计反应','Lifetime reactions'],['comments','累计评论','Lifetime comments']].map(([key,z,e])=>{const m=counterMetric(rows,key);return metricCard(txt(z,e),m.value,channelName(source),txt('平台公开副本的累计计数','Lifetime counter for public platform copies'),m.coverage,m.updated?.replace('T',' ').replace('Z',' UTC'));}).join('')}</div>${rows.length?`<section class="panel metric-table"><h2>${txt('采集记录','Captured records')}</h2>${rows.map(r=>`<div class="workflow-list-row"><div><strong data-i18n-preserve>${esc(articles.find(a=>a.id===r.articleId).langs.en.liveSnapshot.savedTitle)}</strong><small>${r.capturedAt.replace('T',' ')} · ${txt('累计快照','Lifetime snapshot')}</small></div>${badge('EN','neutral')}</div>`).join('')}</section>`:emptyState(txt('没有可用采集值','No available captured values'),txt('可能是渠道未提供数据、当前语言不支持，或区间内没有采集。Unavailable 不等于 0。','The platform may not provide data, the language may be unsupported, or no capture falls in this range. Unavailable does not mean zero.'))}`;};
function distributionInsights(){const all=copyJobs.filter(j=>j.owner===state.workspace&&(site.analyticsArticle==='all'||j.articleId===site.analyticsArticle)&&(site.analyticsLang==='all'||j.lang===site.analyticsLang));const published=all.filter(j=>j.status==='published').length;return `<section class="panel campaign-summary"><div><span class="eyebrow">DISTRIBUTION OUTCOMES</span><h2>${txt('分发活动与结果','Distribution activity & outcomes')}</h2><p>${txt('本次会话的任务记录，与阅读计数分开；日期筛选不影响此任务摘要。','Task records from this session, separate from readership. The date filter does not affect this task summary.')}</p></div><div class="outcome-numbers"><span><b>${all.length}</b>${txt('任务','Tasks')}</span><span><b>${published}</b>${txt('已公开','Published')}</span><span><b>${all.filter(j=>!['published','removed','cancelled'].includes(j.status)).length}</b>${txt('待跟进','To follow up')}</span></div>${routeButton('查看任务','deliveries','','arrow')}</section>`;}
actions['export-analytics']=()=>{if(site.analyticsSource==='ghost'){const d=ghostMetricData();download('ghost-period-demo.csv','date,views,daily_estimated_uv\n'+d.points.map(p=>`${p.day},${p.views},${p.dailyUV}`).join('\n'));}else download('platform-lifetime-demo.csv','source,captured_at,article_id,lifetime_views,lifetime_reactions,lifetime_comments\n'+externalCounters().map(r=>[r.channel,r.capturedAt,r.articleId,r.views??'Unavailable',r.reactions??'Unavailable',r.comments??'Unavailable'].join(',')).join('\n'));};
const consentByHost={};site.privacySignal='none';
function publicHost(){return publicationTarget(site.publicOwner,site.publicLang).displayAddress;}
function privacySignal(){return site.privacySignal==='gpc'||(typeof navigator!=='undefined'&&navigator.globalPrivacyControl)?'gpc':site.privacySignal==='dnt'||(typeof navigator!=='undefined'&&navigator.doNotTrack==='1')?'dnt':null;}
function consentState(host=publicHost()){return privacySignal()?'blocked':consentByHost[host]||'unset';}
function setConsent(choice,host=publicHost()){if(!['accepted','declined'].includes(choice))return false;consentByHost[host]=choice;return true;}
const originalBlogFooter=blogFooter;
blogFooter=function(){const s=consentState();return originalBlogFooter()+`<div class="privacy-footer"><span>${txt('仅为隐私交互演示，不发送阅读统计。','Privacy interaction demo only. No readership events are sent.')}</span>${flowButton('隐私设置','Privacy settings','privacy-open','','quiet sm')}</div>`+(s==='unset'?`<section class="consent-banner" aria-label="${txt('阅读统计选择','Readership analytics choice')}"><div><strong>${txt('允许匿名阅读统计？','Allow anonymous readership analytics?')}</strong><p>${txt('仅针对当前语言站点。拒绝后仍可正常阅读。','This choice applies only to this language site. Declining does not affect reading.')}</p><small>${publicHost()}</small></div><div>${flowButton('拒绝','Decline','privacy-choice','declined')}${flowButton('允许','Allow','privacy-choice','accepted','primary')}</div></section>`:s==='blocked'?`<div class="privacy-signal-note">${privacySignal().toUpperCase()} · ${txt('已优先遵循浏览器隐私信号，统计保持关闭。','Your browser privacy signal takes priority. Analytics remains off.')}</div>`:'');};
flowHandlers['privacy-choice']=choice=>{setConsent(choice);closeModal();render();};
flowHandlers['privacy-open']=()=>{const s=consentState();modal(txt('当前站点隐私设置','Privacy for this site'),`<p>${publicHost()}</p><p>${txt('当前选择','Current choice')}: ${s==='blocked'?privacySignal().toUpperCase():s==='accepted'?txt('允许','Allowed'):s==='declined'?txt('拒绝','Declined'):txt('尚未选择','Not chosen')}</p>${notice(txt('中文与英文语言路径分别保存选择。GPC 或 DNT 优先，撤回同意后立即停止后续统计。此原型始终不会发送统计事件。','Chinese and English language paths keep separate choices. GPC or DNT takes priority; withdrawing consent stops future analytics immediately. This prototype never sends analytics events.'))}`,flowButton('拒绝或撤回','Decline or withdraw','privacy-choice','declined')+(privacySignal()?'':flowButton('允许统计','Allow analytics','privacy-choice','accepted','primary')));};
